package com.hbm.client.oreslopper;
import com.hbm.machine.oreslopper.*;import com.hbm.multiblock.DummyableBlock;import net.minecraft.client.Minecraft;import net.minecraft.core.particles.*;import net.minecraft.world.level.block.Blocks;
/** Exact original cycle, including the source negative residual slider at MOVE_BUCKET completion. */
final class OreSlopperAnimation {
 static void tick(OreSlopperBlockEntity m){m.prevSlider=m.slider;m.prevBucket=m.bucket;m.prevBlades=m.blades;m.prevFan=m.fan;if(!m.processing)return;m.blades+=15;m.fan+=35;if(m.blades>=360){m.blades-=360;m.prevBlades-=360;}if(m.fan>=360){m.fan-=360;m.prevFan-=360;}var p=m.getBlockPos();var level=m.getLevel();var player=Minecraft.getInstance().player;if(m.animation==OreSlopperBlockEntity.Animation.DUMPING&&player!=null&&player.distanceToSqr(p.getX()+.5,p.getY()+4,p.getZ()+.5)<=2500){var d=DummyableBlock.facing(m.getBlockState());var dust=new net.minecraft.client.particle.TerrainParticle((net.minecraft.client.multiplayer.ClientLevel)level,p.getX()+.5+d.getStepX()+level.random.nextGaussian()*.25,p.getY()+4.25,p.getZ()+.5+d.getStepZ()+level.random.nextGaussian()*.25,0,0,0,Blocks.IRON_BLOCK.defaultBlockState());dust.setParticleSpeed(0,0,0);dust.setLifetime(10+level.random.nextInt(20));dust.setColor(.8F,.8F,.8F);Minecraft.getInstance().particleEngine.add(dust);}if(m.delay>0){m.delay--;return;}switch(m.animation){case LOWERING->{m.bucket+=1F/40F;if(m.bucket>=1){m.bucket=1;m.animation=OreSlopperBlockEntity.Animation.LIFTING;m.delay=20;}}case LIFTING->{m.bucket-=1F/40F;if(m.bucket<=0){m.bucket=0;m.animation=OreSlopperBlockEntity.Animation.MOVE_SHREDDER;m.delay=10;}}case MOVE_SHREDDER->{m.slider+=1F/50F;if(m.slider>=1){m.slider=1;m.animation=OreSlopperBlockEntity.Animation.DUMPING;m.delay=60;}}case DUMPING->m.animation=OreSlopperBlockEntity.Animation.MOVE_BUCKET;case MOVE_BUCKET->{m.slider-=1F/50F;if(m.slider<=0){m.animation=OreSlopperBlockEntity.Animation.LOWERING;m.delay=10;}}}}
 private OreSlopperAnimation(){}
}
